// generated by `cargo xtask protocol` from crates/kiln-protocol, do not edit
import type { NodeId } from "./NodeId";
import type { PictureCrop } from "./PictureCrop";
import type { Rect } from "./Rect";
import type { ShapeLook } from "./ShapeLook";
import type { WrapMode } from "./WrapMode";

/**
 * The selected floating or inline object.
 */
export type ObjectInfo = { 
/**
 * The drawing.
 */
id: NodeId, 
/**
 * Its name (`Picture 1`, `Text Box 2`).
 */
name: string, 
/**
 * `Picture`, `Shape`, `TextBox`, `Chart` or `Other`.
 */
kind: string, 
/**
 * Wrapping.
 */
wrap: WrapMode, 
/**
 * The paragraph holding it.
 */
para: NodeId, 
/**
 * Its char offset there.
 */
offset: number, 
/**
 * The rectangle on its page, document coordinates (when laid out).
 */
rect: Rect | null, 
/**
 * Size in points.
 */
width: number, 
/**
 * Size in points.
 */
height: number, 
/**
 * Rotation in degrees.
 */
rotation: number, 
/**
 * Z-order (higher is in front).
 */
z: number, 
/**
 * Alt text.
 */
alt_text: string | null, 
/**
 * Decorative.
 */
decorative: boolean, 
/**
 * The selection is this object.
 */
selected: boolean, 
/**
 * A picture's cropping (`None` for other objects).
 */
crop: PictureCrop | null, 
/**
 * A shape's or text box's look (`None` for pictures, charts and shapes Kiln cannot edit).
 */
shape: ShapeLook | null, 
/**
 * Hidden from the page (the Selection pane's eye, `wp:docPr/@hidden`).
 */
hidden: boolean, 
/**
 * Part of a multiple selection of objects.
 */
in_selection: boolean, };
